import {
  Box,
  Stack,
  Typography,
} from "@mui/material";

import {
  TrendingUpRounded,
  CalendarMonthRounded,
} from "@mui/icons-material";

import {
  Area,
  AreaChart,
  CartesianGrid,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import {
  ForecastFilters,
  ForecastRecord,
} from "../types/forecast.types";

import {
  useForecastChart,
} from "../hooks/useForecast";

interface ForecastTrendChartProps {
  filters: ForecastFilters;
}

interface ForecastChartPoint {
  date: string;
  value: number;
}

const ForecastTrendChart = ({
  filters,
}: ForecastTrendChartProps) => {
  const {
    data,
    isLoading,
    isError,
  } = useForecastChart(filters);

  /*
   * ---------------------------------------------------------
   * METRIC HELPERS
   * ---------------------------------------------------------
   */

  const getMetricLabel = (): string => {
    switch (filters.metric) {
      case "burn":
        return "Burn";

      case "supply":
        return "Supply";

      case "stockpile":
        return "Stockpile";

      default:
        return "Forecast";
    }
  };

  const getMetricDescription = (): string => {
    switch (filters.metric) {
      case "burn":
        return "Projected coal burn across the selected forecast horizon.";

      case "supply":
        return "Projected replenishment requirements across the selected forecast horizon.";

      case "stockpile":
        return "Projected stockpile position across the selected forecast horizon.";

      default:
        return "Forecast projection across the selected horizon.";
    }
  };

  const getMetricUnit = (): string => {
    if (filters.metric === "stockpile") {
      return "tonnes";
    }

    if (filters.horizon === "daily") {
      return "t/day";
    }

    return "tonnes";
  };

  const getMetricValue = (
    record: ForecastRecord
  ): number => {
    switch (filters.metric) {
      case "burn":
        return Number(record.Input);

      case "supply":
        return Number(
          record.Replenishment
        );

      case "stockpile":
        return Number(
          record.Stockpile
        );

      default:
        return Number(record.Input);
    }
  };

  /*
   * ---------------------------------------------------------
   * FORMATTERS
   * ---------------------------------------------------------
   */

  const formatNumber = (
    value: number
  ): string => {
    return new Intl.NumberFormat(
      "en-US",
      {
        maximumFractionDigits: 1,
      }
    )
      .format(value)
      .replace(/,/g, " ");
  };

  const formatDate = (
    value: string
  ): string => {
    const date = new Date(value);

    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return value;
    }

    return date.toLocaleDateString(
      "en-GB",
      {
        day: "2-digit",
        month: "short",
      }
    );
  };

  /*
   * ---------------------------------------------------------
   * CHART DATA
   * ---------------------------------------------------------
   */

  const records: ForecastRecord[] =
    data ?? [];

  const chartData: ForecastChartPoint[] =
    records.map(
      (
        record: ForecastRecord
      ): ForecastChartPoint => ({
        date: record.event_date,
        value: getMetricValue(
          record
        ),
      })
    );

  /*
   * ---------------------------------------------------------
   * DERIVED STATISTICS
   * ---------------------------------------------------------
   */

  const values: number[] =
    chartData.map(
      (
        point: ForecastChartPoint
      ) => point.value
    );

  const average =
    values.length > 0
      ? values.reduce(
          (
            sum: number,
            value: number
          ) => sum + value,
          0
        ) / values.length
      : 0;

  const peak =
    values.length > 0
      ? Math.max(...values)
      : 0;

  const lowest =
    values.length > 0
      ? Math.min(...values)
      : 0;

  const peakIndex =
    values.length > 0
      ? values.indexOf(peak)
      : -1;

  const peakDate =
    peakIndex >= 0
      ? chartData[peakIndex]?.date
      : undefined;

  const firstValue =
    values.length > 0
      ? values[0]
      : 0;

  const lastValue =
    values.length > 0
      ? values[values.length - 1]
      : 0;

  const trendPercentage =
    firstValue !== 0
      ? ((lastValue - firstValue) /
          Math.abs(firstValue)) *
        100
      : 0;

  const isIncreasing =
    lastValue >= firstValue;

  /*
   * ---------------------------------------------------------
   * COLORS
   * ---------------------------------------------------------
   */

  const metricColor =
    filters.metric === "stockpile"
      ? "#2E7D32"
      : filters.metric === "supply"
      ? "#F57C00"
      : "#1264FF";

  const gradientId =
    `forecastTrendGradient-${filters.metric}`;

  /*
   * ---------------------------------------------------------
   * LOADING
   * ---------------------------------------------------------
   */

  if (isLoading) {
    return (
      <Box
        sx={{
          bgcolor: "#FFFFFF",
          border:
            "1px solid #E3E8EF",
          borderRadius: 4,
          p: {
            xs: 2.5,
            md: 3.5,
          },
          minHeight: 520,
          boxShadow:
            "0 4px 18px rgba(23,43,77,0.04)",
        }}
      >
        <Stack
          direction="row"
          spacing={1.5}
          alignItems="center"
        >
          <Box
            sx={{
              width: 44,
              height: 44,
              borderRadius: 2.5,
              bgcolor:
                "rgba(18,100,255,0.08)",
              display: "flex",
              alignItems: "center",
              justifyContent:
                "center",
            }}
          >
            <TrendingUpRounded
              sx={{
                color: "#1264FF",
              }}
            />
          </Box>

          <Box>
            <Typography
              sx={{
                fontSize: 23,
                fontWeight: 800,
                color: "#172B4D",
              }}
            >
              Forecast Trend
            </Typography>

            <Typography
              sx={{
                color: "#6B778C",
                fontSize: 13.5,
                mt: 0.5,
              }}
            >
              Loading forecast data...
            </Typography>
          </Box>
        </Stack>
      </Box>
    );
  }

  /*
   * ---------------------------------------------------------
   * ERROR / EMPTY
   * ---------------------------------------------------------
   */

  if (
    isError ||
    chartData.length === 0
  ) {
    return (
      <Box
        sx={{
          bgcolor: "#FFFFFF",
          border:
            "1px solid #E3E8EF",
          borderRadius: 4,
          minHeight: 520,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          p: 4,
          boxShadow:
            "0 4px 18px rgba(23,43,77,0.04)",
        }}
      >
        <Stack
          alignItems="center"
          spacing={1}
          textAlign="center"
        >
          <TrendingUpRounded
            sx={{
              fontSize: 42,
              color: "#9AA5B5",
            }}
          />

          <Typography
            sx={{
              color: "#172B4D",
              fontWeight: 700,
            }}
          >
            Forecast data unavailable
          </Typography>

          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 13,
              maxWidth: 360,
            }}
          >
            There is no forecast data
            available for the selected
            context.
          </Typography>
        </Stack>
      </Box>
    );
  }

  /*
   * ---------------------------------------------------------
   * RENDER
   * ---------------------------------------------------------
   */

  return (
    <Box
      sx={{
        bgcolor: "#FFFFFF",
        border:
          "1px solid #E3E8EF",
        borderRadius: 4,
        overflow: "hidden",
        boxShadow:
          "0 4px 18px rgba(23,43,77,0.04)",
      }}
    >
      {/* =====================================================
          HEADER
          ===================================================== */}

      <Box
        sx={{
          px: {
            xs: 2.5,
            md: 4,
          },
          pt: {
            xs: 2.5,
            md: 3.5,
          },
          pb: 2,
        }}
      >
        <Stack
          direction={{
            xs: "column",
            md: "row",
          }}
          justifyContent="space-between"
          alignItems={{
            xs: "flex-start",
            md: "center",
          }}
          spacing={2}
        >
          {/* TITLE */}

          <Stack
            direction="row"
            spacing={1.5}
            alignItems="center"
          >
            <Box
              sx={{
                width: 46,
                height: 46,
                borderRadius: 2.5,
                bgcolor:
                  "rgba(18,100,255,0.08)",
                display: "flex",
                alignItems: "center",
                justifyContent:
                  "center",
                flexShrink: 0,
              }}
            >
              <TrendingUpRounded
                sx={{
                  color:
                    metricColor,
                  fontSize: 25,
                }}
              />
            </Box>

            <Box>
              <Typography
                sx={{
                  color: "#172B4D",
                  fontSize: {
                    xs: 21,
                    md: 25,
                  },
                  lineHeight: 1.2,
                  fontWeight: 800,
                  letterSpacing:
                    "-0.02em",
                }}
              >
                {filters.horizon ===
                "daily"
                  ? "Tactical Daily"
                  : "Strategic Monthly"}{" "}
                {getMetricLabel()}{" "}
                Forecast
              </Typography>

              <Typography
                sx={{
                  color: "#6B778C",
                  fontSize: 13.5,
                  mt: 0.5,
                }}
              >
                {getMetricDescription()}
              </Typography>
            </Box>
          </Stack>

          {/* CONTEXT BADGES */}

          <Stack
            direction="row"
            spacing={1}
            flexWrap="wrap"
            useFlexGap
          >
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                gap: 0.75,
                px: 1.25,
                py: 0.75,
                borderRadius: 2,
                bgcolor:
                  "rgba(18,100,255,0.06)",
                border:
                  "1px solid rgba(18,100,255,0.10)",
              }}
            >
              <CalendarMonthRounded
                sx={{
                  fontSize: 17,
                  color:
                    "#1264FF",
                }}
              />

              <Typography
                sx={{
                  fontSize: 12,
                  fontWeight: 700,
                  color:
                    "#172B4D",
                }}
              >
                {filters.horizon ===
                "daily"
                  ? `${chartData.length} Days`
                  : `${chartData.length} Months`}
              </Typography>
            </Box>

            <Box
              sx={{
                px: 1.25,
                py: 0.75,
                borderRadius: 2,
                bgcolor:
                  "rgba(46,125,50,0.07)",
                border:
                  "1px solid rgba(46,125,50,0.10)",
              }}
            >
              <Typography
                sx={{
                  fontSize: 12,
                  fontWeight: 700,
                  color:
                    "#2E7D32",
                }}
              >
                Forecast Generated
              </Typography>
            </Box>
          </Stack>
        </Stack>
      </Box>

      {/* =====================================================
          MINI KPI STRIP
          ===================================================== */}

      <Box
        sx={{
          px: {
            xs: 2.5,
            md: 4,
          },
          pb: 2.5,
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr 1fr",
            md: "repeat(4, 1fr)",
          },
          gap: {
            xs: 1,
            md: 1.5,
          },
        }}
      >
        {/* AVERAGE */}

        <Box
          sx={{
            px: 1.75,
            py: 1.5,
            borderRadius: 2.5,
            bgcolor: "#F7F9FC",
          }}
        >
          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 10.5,
              fontWeight: 800,
              textTransform:
                "uppercase",
              letterSpacing:
                "0.06em",
            }}
          >
            Average
          </Typography>

          <Typography
            sx={{
              color: "#172B4D",
              fontSize: 22,
              fontWeight: 800,
              mt: 0.5,
            }}
          >
            {formatNumber(
              average
            )}
          </Typography>

          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 11,
            }}
          >
            {getMetricUnit()}
          </Typography>
        </Box>

        {/* PEAK */}

        <Box
          sx={{
            px: 1.75,
            py: 1.5,
            borderRadius: 2.5,
            bgcolor: "#F7F9FC",
          }}
        >
          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 10.5,
              fontWeight: 800,
              textTransform:
                "uppercase",
              letterSpacing:
                "0.06em",
            }}
          >
            Peak
          </Typography>

          <Typography
            sx={{
              color:
                metricColor,
              fontSize: 22,
              fontWeight: 800,
              mt: 0.5,
            }}
          >
            {formatNumber(
              peak
            )}
          </Typography>

          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 11,
            }}
          >
            {getMetricUnit()}
          </Typography>
        </Box>

        {/* TREND */}

        <Box
          sx={{
            px: 1.75,
            py: 1.5,
            borderRadius: 2.5,
            bgcolor: "#F7F9FC",
          }}
        >
          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 10.5,
              fontWeight: 800,
              textTransform:
                "uppercase",
              letterSpacing:
                "0.06em",
            }}
          >
            Horizon Trend
          </Typography>

          <Typography
            sx={{
              color:
                isIncreasing
                  ? "#2E7D32"
                  : "#D32F2F",
              fontSize: 22,
              fontWeight: 800,
              mt: 0.5,
            }}
          >
            {trendPercentage >=
            0
              ? "+"
              : ""}
            {trendPercentage.toFixed(
              1
            )}
            %
          </Typography>

          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 11,
            }}
          >
            {isIncreasing
              ? "increase"
              : "decrease"}
          </Typography>
        </Box>

        {/* PERIODS */}

        <Box
          sx={{
            px: 1.75,
            py: 1.5,
            borderRadius: 2.5,
            bgcolor: "#F7F9FC",
          }}
        >
          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 10.5,
              fontWeight: 800,
              textTransform:
                "uppercase",
              letterSpacing:
                "0.06em",
            }}
          >
            Periods
          </Typography>

          <Typography
            sx={{
              color: "#172B4D",
              fontSize: 22,
              fontWeight: 800,
              mt: 0.5,
            }}
          >
            {chartData.length}
          </Typography>

          <Typography
            sx={{
              color: "#6B778C",
              fontSize: 11,
            }}
          >
            forecast points
          </Typography>
        </Box>
      </Box>

      {/* =====================================================
          CHART
          ===================================================== */}

      <Box
        sx={{
          width: "100%",
          height: {
            xs: 340,
            sm: 390,
            md: 430,
          },
          px: {
            xs: 1,
            md: 2,
          },
        }}
      >
        <ResponsiveContainer
          width="100%"
          height="100%"
        >
          <AreaChart
            data={chartData}
            margin={{
              top: 15,
              right: 20,
              left: 5,
              bottom: 10,
            }}
          >
            <defs>
              <linearGradient
                id={gradientId}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >
                <stop
                  offset="0%"
                  stopColor={
                    metricColor
                  }
                  stopOpacity={0.22}
                />

                <stop
                  offset="70%"
                  stopColor={
                    metricColor
                  }
                  stopOpacity={0.06}
                />

                <stop
                  offset="100%"
                  stopColor={
                    metricColor
                  }
                  stopOpacity={0}
                />
              </linearGradient>
            </defs>

            <CartesianGrid
              strokeDasharray="3 7"
              vertical={false}
              stroke="#E8ECF2"
            />

            <XAxis
              dataKey="date"
              tickFormatter={
                formatDate
              }
              tick={{
                fill: "#7A869A",
                fontSize: 11,
              }}
              axisLine={false}
              tickLine={false}
              minTickGap={45}
            />

            <YAxis
              tickFormatter={(
                value: number
              ) =>
                formatNumber(
                  value
                )
              }
              tick={{
                fill: "#7A869A",
                fontSize: 11,
              }}
              axisLine={false}
              tickLine={false}
              width={65}
              domain={[
                "auto",
                "auto",
              ]}
            />

            {/* AVERAGE LINE */}

            <ReferenceLine
              y={average}
              stroke="#9AA5B5"
              strokeDasharray="5 5"
              strokeWidth={1.5}
              label={{
                value: `Average ${formatNumber(
                  average
                )}`,
                position:
                  "insideTopRight",
                fill: "#7A869A",
                fontSize: 11,
              }}
            />

            <Tooltip
              cursor={{
                stroke:
                  metricColor,
                strokeWidth: 1,
                strokeDasharray:
                  "4 4",
              }}
              formatter={(
                value: number
              ) => [
                `${formatNumber(
                  value
                )} ${getMetricUnit()}`,
                getMetricLabel(),
              ]}
              labelFormatter={(
                label
              ) =>
                formatDate(
                  String(label)
                )
              }
              contentStyle={{
                background:
                  "#FFFFFF",
                border:
                  "1px solid #E3E8EF",
                borderRadius: 12,
                padding:
                  "10px 14px",
                boxShadow:
                  "0 12px 30px rgba(23,43,77,0.12)",
              }}
              labelStyle={{
                color:
                  "#172B4D",
                fontWeight: 700,
                marginBottom: 4,
              }}
              itemStyle={{
                color:
                  metricColor,
                fontWeight: 700,
              }}
            />

            <Area
              type="monotone"
              dataKey="value"
              stroke={
                metricColor
              }
              strokeWidth={3}
              fill={`url(#${gradientId})`}
              activeDot={{
                r: 6,
                stroke:
                  "#FFFFFF",
                strokeWidth: 3,
                fill:
                  metricColor,
              }}
              dot={
                chartData.length <=
                30
                  ? {
                      r: 3,
                      fill:
                        "#FFFFFF",
                      stroke:
                        metricColor,
                      strokeWidth: 2,
                    }
                  : false
              }
            />
          </AreaChart>
        </ResponsiveContainer>
      </Box>

      {/* =====================================================
          FOOTER / PEAK INFORMATION
          ===================================================== */}

      <Box
        sx={{
          mx: {
            xs: 2.5,
            md: 4,
          },
          mt: 1,
          mb: {
            xs: 2.5,
            md: 3.5,
          },
          pt: 2.5,
          borderTop:
            "1px solid #E8ECF2",
        }}
      >
        <Stack
          direction={{
            xs: "column",
            sm: "row",
          }}
          justifyContent="space-between"
          spacing={2}
        >
          {/* LOWEST */}

          <Box>
            <Typography
              sx={{
                color: "#6B778C",
                fontSize: 11,
                fontWeight: 700,
              }}
            >
              LOWEST PROJECTED
            </Typography>

            <Typography
              sx={{
                color:
                  lowest < 0
                    ? "#D32F2F"
                    : "#172B4D",
                fontSize: 18,
                fontWeight: 800,
                mt: 0.5,
              }}
            >
              {formatNumber(
                lowest
              )}{" "}
              {getMetricUnit()}
            </Typography>
          </Box>

          {/* PEAK */}

          <Box
            sx={{
              textAlign: {
                xs: "left",
                sm: "right",
              },
            }}
          >
            <Typography
              sx={{
                color: "#6B778C",
                fontSize: 11,
                fontWeight: 700,
              }}
            >
              PEAK PROJECTED
            </Typography>

            <Typography
              sx={{
                color:
                  metricColor,
                fontSize: 18,
                fontWeight: 800,
                mt: 0.5,
              }}
            >
              {formatNumber(
                peak
              )}{" "}
              {getMetricUnit()}
            </Typography>

            {peakDate && (
              <Typography
                sx={{
                  color:
                    "#6B778C",
                  fontSize: 11,
                  mt: 0.25,
                }}
              >
                Expected around{" "}
                {formatDate(
                  peakDate
                )}
              </Typography>
            )}
          </Box>
        </Stack>
      </Box>
    </Box>
  );
};

export default ForecastTrendChart;
